* @param {params} params
* @param {api} params.api
* @param {any} params.event
*/
function evaluateEvent({api, event}) {
	var pageid = 'mid-setup-step1';
	var requiredP = {};
	var optionalP = {};
	if(api.context.props.authType == 'ipki'){
		pageid = 'mid-setup-step2';
		requiredP = {
			"authType" : api.context.props.authType,
			"installMethod": api.context.props.installMethod,
			"midServerOS": api.context.props.midServerOS
		};
		optionalP = {
			"midServerName": api.context.props.midServerName,
			"midServerPurpose": api.context.props.midServerPurpose,
			"midServerUser": api.context.props.midServerUser,
			"midServerProxyHost": api.context.props.midServerProxyHost,
			"midServerProxyPort": api.context.props.midServerProxyPort,
			"midServerServiceName": api.context.props.midServerServiceName,
		};
	}

	return {
		pageID: pageid,
		requiredParams: requiredP,
		optionalParams: optionalP
	};
})

