	var file = "";

	switch (api.context.props.installMethod) {
        case 'docker':
            file = 'linux64DockerRecipe';
			break;
        case 'deb':
            file = 'linux64DEBSign';
			break;
        case 'rpm':
            file = 'linux64RPMSign';
			break;
    }

	return {
		propName: "buttonPayload",
		value: {
			"action": "downloadFile",
			"downloadFile": {"value":file}
		}
	};
})

